fn solve(s: Vec<char>) -> &'static str {
    let mut stack: Vec<char> = Vec::new();
    let mut removed_pairs = 0;

    for c in s {
        if stack.last() == Some(&c) {
            // Found an adjacent equal pair, remove it
            stack.pop();
            removed_pairs += 1;
        } else {
            // No match, push onto stack
            stack.push(c);
        }
    }

    if removed_pairs % 2 == 1 {
        "Yes"
    } else {
        "No"
    }
}

